/* @flow strict-local */

import { typesEquivalent } from '../generics';
import { objectValues } from '../flowPonyfill';

/**
 * Organization-level role of a user.
 *
 * Described in the server API doc, e.g., at `.role` in `realm_users` at
 *   https://zulip.com/api/register-queue
 */
export enum Role {
  Owner = 100,
  Admin = 200,
  Moderator = 300,
  Member = 400,
  Guest = 600,
}

/**
 * This organization's policy for which users can create public streams, or
 *   its policy for which users can create private streams.
 *
 * (These policies could be set differently, but their types are the same,
 * so it's convenient to have just one definition.)
 *
 * For the policy for web-public streams, see CreateWebPublicStreamPolicy.
 */
// eslint-disable-next-line ft-flow/type-id-match
export type CreatePublicOrPrivateStreamPolicyT = 1 | 2 | 3 | 4;

/**
 * An enum of all valid values for `CreatePublicOrPrivateStreamPolicyT`.
 *
 * See CreatePublicOrPrivateStreamPolicyValues for the list of values.
 */
// Ideally both the type and enum would have the simple name; but a type
// and value sharing a name is one nice TS feature that Flow lacks.
// Or we could leapfrog TS and make this a Flow enum:
//   https://flow.org/en/docs/enums/
// (TS has its own enums, but they are a mess.)
export const CreatePublicOrPrivateStreamPolicy = {
  MemberOrAbove: (1: 1),
  AdminOrAbove: (2: 2),
  FullMemberOrAbove: (3: 3),
  ModeratorOrAbove: (4: 4),
};

// Check that the enum indeed has all and exactly the values of the type.
typesEquivalent<
  CreatePublicOrPrivateStreamPolicyT,
  $Values<typeof CreatePublicOrPrivateStreamPolicy>,
>();

/**
 * A list of all valid values for `CreatePublicOrPrivateStreamPolicyT`.
 *
 * See CreatePublicOrPrivateStreamPolicy for an enum to refer to these by
 * meaningful names.
 */
export const CreatePublicOrPrivateStreamPolicyValues: $ReadOnlyArray<CreatePublicOrPrivateStreamPolicyT> =
  objectValues(CreatePublicOrPrivateStreamPolicy);

/**
 * The policy for which users can create web public streams in this
 * organization. Ignore if the server hasn't opted into the concept of
 * web-public streams.
 */
export enum CreateWebPublicStreamPolicy {
  AdminOrAbove = 2,
  ModeratorOrAbove = 4,
  Nobody = 6,
  OwnerOnly = 7,
}

/**
 * The policy for who in the organization has access to users' actual email
 */
export enum EmailAddressVisibility {
  Everyone = 1,
  Members = 2,
  Admins = 3,
  Nobody = 4,
  Moderators = 5,
}

/* @flow strict-local */
import deepFreeze from 'deep-freeze';

import getComposeInputPlaceholder from '../getComposeInputPlaceholder';
import {
  pm1to1NarrowFromUser,
  streamNarrow,
  topicNarrow,
  pmNarrowFromUsersUnsafe,
} from '../../utils/narrow';
import * as eg from '../../__tests__/lib/exampleData';
import { getStreamsById } from '../../selectors';
import { mock_ } from '../../__tests__/lib/intl';

describe('getComposeInputPlaceholder', () => {
  const usersById = new Map([eg.selfUser, eg.otherUser, eg.thirdUser].map(u => [u.user_id, u]));
  const ownUserId = eg.selfUser.user_id;
  const streamsById = getStreamsById(eg.plusReduxState);

  test('returns "Message This Person" object for person narrow', () => {
    const narrow = deepFreeze(pm1to1NarrowFromUser(eg.otherUser));
    const placeholder = getComposeInputPlaceholder(
      narrow,
      ownUserId,
      usersById,
      streamsById,
      false,
      mock_,
    );
    expect(placeholder).toEqual({
      text: 'Message {recipient}',
      values: { recipient: eg.otherUser.full_name },
    });
  });

  test('returns "Jot down something" object for self narrow', () => {
    const narrow = deepFreeze(pm1to1NarrowFromUser(eg.selfUser));
    const placeholder = getComposeInputPlaceholder(
      narrow,
      ownUserId,
      usersById,
      streamsById,
      false,
      mock_,
    );
    expect(placeholder).toEqual({ text: 'Jot down something' });
  });

  test('returns "Message #streamName" for stream narrow', () => {
    const narrow = deepFreeze(streamNarrow(eg.stream.stream_id));
    const placeholder = getComposeInputPlaceholder(
      narrow,
      ownUserId,
      usersById,
      streamsById,
      false,
      mock_,
    );
    expect(placeholder).toEqual({
      text: 'Message {recipient}',
      values: { recipient: `#${eg.stream.name}` },
    });
  });

  test('returns properly for topic narrow', () => {
    const narrow = deepFreeze(topicNarrow(eg.stream.stream_id, 'Copenhagen'));
    const placeholder = getComposeInputPlaceholder(
      narrow,
      ownUserId,
      usersById,
      streamsById,
      false,
      mock_,
    );
    expect(placeholder).toEqual({ text: 'Reply' });
  });

  test('returns "Message group" object for group narrow', () => {
    const narrow = deepFreeze(pmNarrowFromUsersUnsafe([eg.otherUser, eg.thirdUser]));
    const placeholder = getComposeInputPlaceholder(
      narrow,
      ownUserId,
      usersById,
      streamsById,
      false,
      mock_,
    );
    expect(placeholder).toEqual({ text: 'Message group' });
  });
});

/* @flow strict-local */
import * as logging from '../../utils/logging';
import { chooseUploadImageFilename } from '../ComposeMenu';

describe('chooseUploadImageFilename', () => {
  test('Does nothing if the image uri does not end with an extension for the JPEG format', () => {
    expect(chooseUploadImageFilename('foo', 'foo')).toBe('foo');
  });

  test(
    'Replaces any extension for the HEIC format with an extension for the JPEG format '
      + 'if the file name does end with an extension for the JPEG format',
    () => {
      // suppress `logging.warn` output
      // $FlowFixMe[prop-missing]: Jest mock
      logging.warn.mockReturnValue();

      const fileNameWithoutExtension = 'foo';
      expect(
        chooseUploadImageFilename('some/path/something.jpg', `${fileNameWithoutExtension}.heic`),
      ).toBe(`${fileNameWithoutExtension}.jpeg`);
    },
  );

  test('Replaces prefix from react-native-image-picker', () => {
    expect(
      chooseUploadImageFilename('some/path/something.jpg', 'rn_image_picker_lib_temp_asdf.jpg'),
    ).toBe('asdf.jpg');
  });
});

import deepFreeze from 'deep-freeze';

import aggregateReactions from '../aggregateReactions';

describe('aggregateReactions', () => {
  test('empty input results in empty aggregate list', () => {
    const reactions = deepFreeze([]);

    const expectedResult = [];

    const actualResult = aggregateReactions(reactions);

    expect(actualResult).toEqual(expectedResult);
  });

  test('a single reaction, results in a single aggregate', () => {
    const reactions = deepFreeze([{ emoji_name: 'emoji', user_id: 3 }]);

    const expectedResult = [
      {
        name: 'emoji',
        count: 1,
        selfReacted: false,
        users: [3],
      },
    ];

    const actualResult = aggregateReactions(reactions, 1);

    expect(actualResult).toEqual(expectedResult);
  });

  test('every duplicate reaction is aggregated to a single one with appropriate count', () => {
    const reactions = deepFreeze([
      { emoji_name: '1', user_id: 1 },
      { emoji_name: '2', user_id: 2 },
      { emoji_name: '1', user_id: 3 },
      { emoji_name: '1', user_id: 4 },
      { emoji_name: '3', user_id: 5 },
      { emoji_name: '2', user_id: 6 },
    ]);

    const expectedResult = [
      {
        name: '1',
        count: 3,
        selfReacted: true,
        users: [1, 3, 4],
      },
      {
        name: '2',
        count: 2,
        selfReacted: false,
        users: [2, 6],
      },
      {
        name: '3',
        count: 1,
        selfReacted: false,
        users: [5],
      },
    ];

    const actualResult = aggregateReactions(reactions, 1);

    expect(actualResult).toEqual(expectedResult);
  });

  test('every duplicate reaction is aggregated, ignoring self', () => {
    const reactions = deepFreeze([
      { emoji_name: '1', user_id: 1 },
      { emoji_name: '2', user_id: 2 },
      { emoji_name: '2', user_id: 1 },
      { emoji_name: '3', user_id: 3 },
    ]);

    const expectedResult = [
      {
        name: '2',
        count: 2,
        selfReacted: true,
        users: [2, 1],
      },
      {
        name: '1',
        count: 1,
        selfReacted: false,
        users: [1],
      },
      {
        name: '3',
        count: 1,
        selfReacted: false,
        users: [3],
      },
    ];

    const actualResult = aggregateReactions(reactions, 2);

    expect(actualResult).toEqual(expectedResult);
  });
});

/* @flow strict-local */
import deepFreeze from 'deep-freeze';

import { navigateBack } from '../navActions';
import * as NavigationService from '../NavigationService';

describe('navigateBack', () => {
  test('if no routes the count of same routes is 0', () => {
    // $FlowFixMe[cannot-write] Make Flow understand about mocking.
    NavigationService.getState = jest.fn().mockReturnValue(
      deepFreeze({
        routes: [],
      }),
    );

    const action = navigateBack();
    expect(action).toMatchObject({ type: 'POP', payload: { count: 0 } });
  });

  test('if last route differs from  routes the count of same routes is 0', () => {
    // $FlowFixMe[cannot-write] Make Flow understand about mocking.
    NavigationService.getState = jest.fn().mockReturnValue(
      deepFreeze({
        routes: [{ name: 'main-tabs' }, { name: 'chat' }],
      }),
    );

    const action = navigateBack();
    expect(action).toMatchObject({ type: 'POP', payload: { count: 1 } });
  });

  test('if several of the routes are the same ignore the params and return their count', () => {
    // $FlowFixMe[cannot-write] Make Flow understand about mocking.
    NavigationService.getState = jest.fn().mockReturnValue(
      deepFreeze({
        routes: [
          { name: 'login' },
          { name: 'main-tabs' },
          { name: 'chat', params: { key: 'value' } },
          { name: 'chat', params: { key: 'another value' } },
          { name: 'chat', params: { anotherKey: 'some value' } },
        ],
      }),
    );

    const action = navigateBack();
    expect(action).toMatchObject({ type: 'POP', payload: { count: 3 } });
  });
});

/* @flow strict-local */
import invariant from 'invariant';

import * as logging from '../../utils/logging';
import * as eg from '../../__tests__/lib/exampleData';
import eventToAction from '../eventToAction';
import { EVENT_NEW_MESSAGE } from '../../actionConstants';
import { AvatarURL } from '../../utils/avatar';

function actionMatchesType(action, type): boolean %checks {
  return action !== null && action.type === type;
}

describe('eventToAction', () => {
  const state = eg.plusReduxState;

  test('filter out unknown event type', () => {
    // $FlowFixMe[prop-missing]: teach Flow about Jest mocks
    logging.error.mockReturnValue();

    expect(eventToAction(state, { type: 'some unknown type' })).toBe(null);

    // $FlowFixMe[prop-missing]: teach Flow about Jest mocks
    expect(logging.error.mock.calls).toHaveLength(1);
    // $FlowFixMe[prop-missing]: teach Flow about Jest mocks
    logging.error.mockReset();
  });

  test('filter out a known boring event type', () => {
    const event = { type: 'heartbeat' };
    expect(eventToAction(state, event)).toBe(null);
  });

  test('for known event, process and return', () => {
    const event = { type: 'presence' };
    const action = eventToAction(state, event);
    expect(action).not.toBe(null);
  });

  describe('type: message', () => {
    const serverMessage = {
      ...eg.streamMessage(),
      reactions: [],
      avatar_url: null,
      edit_history: [
        {
          prev_content: 'foo',
          prev_rendered_content: '<p>foo</p>',
          prev_stream: eg.stream.stream_id,
          prev_topic: 'bar',
          stream: eg.otherStream.stream_id,
          timestamp: 0,
          topic: 'bar!',
          user_id: eg.selfUser.user_id,
        },
      ],
      flags: undefined,
    };

    describe('recent servers', () => {
      const event = { type: 'message', message: serverMessage, flags: ['read'] };
      const action = eventToAction(state, event);

      test('EVENT_NEW_MESSAGE produced', () => {
        expect(actionMatchesType(action, EVENT_NEW_MESSAGE)).toBeTrue();
      });

      invariant(actionMatchesType(action, EVENT_NEW_MESSAGE), 'EVENT_NEW_MESSAGE produced');

      test('Adds event.flags', () => {
        expect(action.message.flags).toEqual(['read']);
      });

      test('Converts avatar_url', () => {
        expect(action.message.avatar_url).toBeInstanceOf(AvatarURL);
      });

      test('Keeps edit_history if allowEditHistory is true', () => {
        // eslint-disable-next-line no-shadow
        const action = eventToAction(
          eg.reduxStatePlus({ realm: { ...eg.plusReduxState.realm, allowEditHistory: true } }),
          event,
        );
        invariant(actionMatchesType(action, EVENT_NEW_MESSAGE), 'EVENT_NEW_MESSAGE produced');
        expect(action.message.edit_history).not.toBeNull();
        expect(action.message.edit_history).toEqual(serverMessage.edit_history);
      });

      test('Drops edit_history if allowEditHistory is false', () => {
        // eslint-disable-next-line no-shadow
        const action = eventToAction(
          eg.reduxStatePlus({ realm: { ...eg.plusReduxState.realm, allowEditHistory: false } }),
          event,
        );
        invariant(actionMatchesType(action, EVENT_NEW_MESSAGE), 'EVENT_NEW_MESSAGE produced');
        expect(action.message.edit_history).toBeNull();
      });
    });

    describe('edit_history for FL <118', () => {
      const serverMessageInner = {
        ...serverMessage,
        edit_history: [
          {
            prev_content: 'foo',
            prev_rendered_content: '<p>foo</p>',
            prev_stream: eg.stream.stream_id,
            prev_subject: 'bar',
            timestamp: 0,
            user_id: eg.selfUser.user_id,
          },
        ],
      };
      const event = { type: 'message', message: serverMessageInner };
      const action = eventToAction(
        eg.reduxStatePlus({
          accounts: [{ ...eg.plusReduxState.accounts[0], zulipFeatureLevel: 117 }],
        }),
        event,
      );

      test('EVENT_NEW_MESSAGE produced', () => {
        expect(actionMatchesType(action, EVENT_NEW_MESSAGE)).toBeTrue();
      });

      invariant(actionMatchesType(action, EVENT_NEW_MESSAGE), 'EVENT_NEW_MESSAGE produced');

      test('edit_history dropped', () => {
        expect(action.message.edit_history).toBeNull();
      });
    });
  });
});

// @flow strict-local
import deepFreeze from 'deep-freeze';
import * as resolved_topic from '@zulip/shared/lib/resolved_topic';

import { HOME_NARROW } from '../../utils/narrow';
import * as eg from '../../__tests__/lib/exampleData';
import {
  constructMessageActionButtons,
  constructTopicActionButtons,
  constructStreamActionButtons,
} from '../index';
import { makeUnreadState } from '../../unread/__tests__/unread-testlib';
import { makeMuteState } from '../../mute/__tests__/mute-testlib';
import { Role } from '../../api/permissionsTypes';
import { UserTopicVisibilityPolicy } from '../../api/modelTypes';

const buttonTitles = buttons => buttons.map(button => button.title);

describe('constructStreamActionButtons', () => {
  const streamId = eg.stream.stream_id;

  const titles = backgroundData =>
    buttonTitles(constructStreamActionButtons({ backgroundData, streamId }));

  // TODO: test constructStreamActionButtons for mute/unmute

  // TODO: test constructStreamActionButtons for copyLinkToStream

  test('show pinToTop', () => {
    const subscriptions = new Map([
      [eg.stream.stream_id, eg.makeSubscription({ pin_to_top: false })],
    ]);
    expect(titles({ ...eg.plusBackgroundData, subscriptions })).toContain('Pin to top');
  });

  test('show unpinFromTop', () => {
    const subscriptions = new Map([
      [eg.stream.stream_id, eg.makeSubscription({ pin_to_top: true })],
    ]);
    expect(titles({ ...eg.plusBackgroundData, subscriptions })).toContain('Unpin from top');
  });

  test('show enableNotifications', () => {
    const subscriptions = new Map([
      [eg.stream.stream_id, eg.makeSubscription({ push_notifications: false })],
    ]);
    expect(titles({ ...eg.plusBackgroundData, subscriptions })).toContain('Enable notifications');
  });

  test('show disableNotifications', () => {
    const subscriptions = new Map([
      [eg.stream.stream_id, eg.makeSubscription({ push_notifications: true })],
    ]);
    expect(titles({ ...eg.plusBackgroundData, subscriptions })).toContain('Disable notifications');
  });

  test('show subscribe', () => {
    expect(titles({ ...eg.plusBackgroundData, subscriptions: new Map() })).toContain('Subscribe');
  });

  test('show unsubscribe', () => {
    expect(titles({ ...eg.plusBackgroundData })).toContain('Unsubscribe');
  });

  // TODO: test constructStreamActionButtons for showStreamSettings
});

describe('constructTopicActionButtons', () => {
  const streamMessage = eg.streamMessage();
  const topic = streamMessage.subject;
  const streamId = eg.stream.stream_id;

  const titles = (backgroundData, topic_) =>
    buttonTitles(constructTopicActionButtons({ backgroundData, streamId, topic: topic_ ?? topic }));

  test('show markTopicAsRead', () => {
    const unread = makeUnreadState(eg.plusReduxState, [streamMessage]);
    expect(titles({ ...eg.plusBackgroundData, unread })).toContain('Mark topic as read');
  });

  test('hide markTopicAsRead', () => {
    const unread = makeUnreadState(eg.plusReduxState, []);
    expect(titles({ ...eg.plusBackgroundData, unread })).not.toContain('Mark topic as read');
  });

  test('show unmuteTopic', () => {
    const mute = makeMuteState([[eg.stream, topic]]);
    expect(titles({ ...eg.plusBackgroundData, mute })).toContain('Unmute topic');
  });

  test('show muteTopic', () => {
    const mute = makeMuteState([]);
    expect(titles({ ...eg.plusBackgroundData, mute })).toContain('Mute topic');
  });

  test('show muteTopic on followed topic', () => {
    const mute = makeMuteState([[eg.stream, topic, UserTopicVisibilityPolicy.Followed]]);
    expect(titles({ ...eg.plusBackgroundData, mute })).toContain('Mute topic');
  });

  test('show followTopic on muted topic', () => {
    const mute = makeMuteState([[eg.stream, topic]]);
    expect(titles({ ...eg.plusBackgroundData, mute })).toContain('Follow topic');
  });

  test('show followTopic', () => {
    const mute = makeMuteState([]);
    expect(titles({ ...eg.plusBackgroundData, mute })).toContain('Follow topic');
  });

  test('show unfollowTopic', () => {
    const mute = makeMuteState([[eg.stream, topic, UserTopicVisibilityPolicy.Followed]]);
    expect(titles({ ...eg.plusBackgroundData, mute })).toContain('Unfollow topic');
  });

  test('show resolveTopic', () => {
